layers.vertex:
attribute vec3 aO; attribute float aYaw, aT; uniform float uTime; varying vec2 vF; varying float vU;
    void main(){
      float u = uTime - aT - 0.12; if (u < 0. || u > .68){ gl_Position = vec4(2.,2.,2.,1.); return; }
      float S = 1.80; vec2 l = position.xy*S;             // local: x right, y forward
      float c = cos(aYaw), s = sin(aYaw);
      vec2 w = vec2(c*l.x - s*l.y, -(s*l.x + c*l.y));      // forward = -z
      vF = l; vU = u;
      gl_Position = projectionMatrix*viewMatrix*vec4(aO + vec3(w.x, 1.05 - l.x*.12, w.y), 1.);  // slight tilt
    }

layers.fragment:
uniform vec3 uGold, uOrange; varying vec2 vF; varying float vU;
    void main(){
      vec2 p = vF; float r = length(p), a = atan(p.x, p.y), SPAN = 1.20;
      float s = clamp((SPAN - a)/(2.*SPAN), 0., 1.);        // 0 = where the swing starts (right), 1 = leading edge (left)
      float edgeA = smoothstep(SPAN + .02, SPAN - .08, abs(a)); // soft angular limit (no hard radial line)
      float prof = sin(3.14159*s);
      float mid = pow(prof, 3.);                              // the thick centre
      // 1) draws out in the swing direction  2) holds  3) fades from the origin, the centre goes last
      float grow = 1. - pow(1. - clamp(vU/.09, 0., 1.), 2.);
      float wipe = max(vU - .23, 0.)/.34;
      float alive = smoothstep(grow + .02, grow - .03, s) * smoothstep(wipe - .08 - .3*mid, wipe + .2 - .3*mid, s);
      float fade = 1. - smoothstep(.5, .68, vU);
      float thin = 1. - .4*smoothstep(.2, .62, vU)*(1. - .5*mid);
      // just the arc: thin at both ends, thick in the middle, with a gentle ease at the tips
      float ends = pow(prof, .75);
      float rr = 1.25 - .06*(1. - s);
      float w = (.004 + .1*pow(prof, 1.3) + .2*mid)*thin;
      float d = r - rr;
      float band = exp(-pow(abs(d)/w, 2.4));                  // flatter core, crisp but soft edge
      float core = exp(-pow(abs(d)/(w*.35), 2.));
      float head = exp(-pow((s - grow)/.035, 2.)) * (1. - step(1., grow));
      float k = alive*fade*edgeA*ends*(vU > .09 && vU < .123 ? 1.25 : 1.);
      vec3 col = mix(uOrange, uGold, .35 + .65*prof);
      vec3 outc = (col*band*(.55 + .5*prof) + mix(uGold, vec3(1., .96, .88), .6)*(core*.55*prof + head*band*.6))*k;
      if (max(outc.r, max(outc.g, outc.b)) < .002) discard;
      gl_FragColor = vec4(outc, 1.);
    }
